local M = class("PetardShopControl",LikeOO.OOControlBase)

function M:onEnter()
    M.super.onCreate(self)
end

function M:onHandle(msg , data)
    if msg == 99999 then
        self:closeView()
    elseif msg == "explain_btn" then
        -- 提示  
        local flowerData = ConfigManager:getCfgByName("flower")
        local versionData = flowerData[self.m_model.m_version]
        self:openView("Pops.CommonHelpPop", { title = self.m_model.m_mainActivityName, content = versionData.des })
    elseif msg == "btn_buyBtn" then
        local params = {
            text = Language:getTextByKey("petard_text_0027",data.price).."?",
            on_ok_call = function ()
                self.m_model:getNetData("double_twelve_exchange_goods", {version = data.version, pos = data.pos}, function(response)
                    if response then
                        if self:activityOverExamine(response) then
                            return
                        end
                        RewardUtil:rewardTipsByData(response.reward)
                        EventDispatcher:dipatchEvent("forceRefresh_petardInfoData")
                    end
                end, nil, nil, nil)
            end
        }
        self:openView("Pops.CommonPop", params)
    end
end

function M:activityOverExamine(response)
    if response["end"] == 1 then
        GameUtil:lookInfoTips(self, {msg = Language:getTextByKey("gf_str_0085"), delay_close = 2})
        self:closeView("PetardActivity.PetardMain")
        self:closeView()
        return true
    end
    return false
end

function M:destroy()
    M.super.destroy(self)
end

return M